; Title character animation
; $7487-$749a

; Rotates the 8 bytes of character 0 of the charset at $2000 up by one byte. The title IRQ calls it every fourth time.
rotate_title_char
        ldy charset_text
        ldx #$00
rotate_title_char_loop
        lda $2001,x
        sta charset_text,x
        inx
        cpx #$07
        bne rotate_title_char_loop
        sty $2007
        rts
